/**
 * Exercise actual browser authoring/retrieval controls while proving this preview makes no durability claim.
 * Symbol index (generated by tools/update-symbol-index.ts):
 * @@SYMBOL_INDEX_START
 * - no top-level symbols
 * @@SYMBOL_INDEX_END
 */
import AxeBuilder from "@axe-core/playwright";
import { expect, test } from "@playwright/test";

test("browser preview validates and compares an actual edited catalog without claiming persistence", async ({
  page,
}) => {
  await page.goto("/workbench/");
  await expect(page.locator("#workspace-mode")).toContainText("edits are temporary");
  await page.locator("#product-select").selectOption("apex-control-hub");
  await page.locator("#version-value").fill("2.1");
  await page.locator("#version-lifecycle").selectOption("current");
  await page.locator("#version-release").fill("2026-11-11");
  await page.locator("#version-clone").selectOption("2.0");
  await page.getByRole("button", { name: "Apply edition", exact: true }).click();
  await page.locator("#topic-select").selectOption("apex-2-0-e104-2-1");
  await page.locator("#topic-title").fill("Review E-104 for edition 2.1");
  await page.getByRole("button", { name: "Validate & apply topic", exact: true }).click();
  await expect(page.locator("#topic-preview")).toContainText("Review E-104 for edition 2.1");
  await page.getByRole("button", { name: "Search & compare", exact: true }).click();
  await page.locator("#workspace-query").fill("E-104");
  await page.locator("#search-product").selectOption("apex-control-hub");
  await page.locator("#search-version").selectOption("2.1");
  await page.getByRole("button", { name: "Search catalog", exact: true }).click();
  await expect(page.locator("#workspace-results")).toContainText("Review E-104 for edition 2.1");
  await page.locator("#save-catalog").click();
  await expect(page.locator("#workspace-error")).toContainText("native app to save durable");
  await page.reload();
  await expect(page.locator("#workspace-status")).toContainText("2 products · 12 topics");
});
test("workspace controls, long hashes and navigation reflow accessibly", async ({ page }) => {
  await page.goto("/workbench/");
  await expect(page.locator("#workspace-status")).toContainText("browser preview only");
  await page.getByRole("button", { name: "History & help", exact: true }).click();
  const audit = await new AxeBuilder({ page })
    .withTags(["wcag2a", "wcag2aa", "wcag21aa", "wcag22aa"])
    .analyze();
  expect(audit.violations).toEqual([]);
  for (const width of [320, 390]) {
    await page.setViewportSize({ width, height: 900 });
    expect(await page.evaluate(() => document.documentElement.scrollWidth > innerWidth)).toBe(
      false,
    );
    for (const item of await page.locator(".site-header nav a").evaluateAll((nodes) =>
      nodes.map((link) => ({
        left: link.getBoundingClientRect().left,
        right: link.getBoundingClientRect().right,
      })),
    )) {
      expect(item.left).toBeGreaterThanOrEqual(0);
      expect(item.right).toBeLessThanOrEqual(width);
    }
  }
});
